namespace Tests;
public class AdminProductReadTests(ApiFactory f):ApiTest(f)
{
    [Fact]public async Task Admin_product_list_pending_nulls_last_filters_counts_detail_and_denied()
    {
        var admin=await Admin();var seller=await LoginPhone("9890000071");var r=await seller.Post("/api/seller/register",new{display_name="Synthetic Read Store"});var sid=r.Json["id"]!.GetValue<string>();var cat=Guid.NewGuid();await ApiFactory.DbExecAsync("INSERT INTO categories(id,name,slug,image_url,commission_bps,default_gst_bps,position,is_active,required_details)VALUES(@cat,'Read Category','read-category','',500,500,0,1,'[]')",new{cat});var ids=new[]{Guid.NewGuid(),Guid.NewGuid(),Guid.NewGuid()};
        for(var i=0;i<3;i++)await ApiFactory.DbExecAsync("INSERT INTO products (id,seller_id,category_id,title,slug,brand,description,highlights,specs,hsn_code,gst_bps,country_of_origin,return_window_days,status,rejection_reason,price_from,mrp_from,in_stock,rating_avg,rating_count,sold_count,details,submitted_at) VALUES (@id,@sid,@cat,@title,@slug,'Acme','Synthetic description','[]','{}','6205',500,'India',7,'pending','',10000,20000,1,0,0,0,'{}',@submitted)",new{id=ids[i],sid,cat,title="Synthetic Product "+i,slug="synthetic-product-"+i,submitted=i==0?(DateTime?)null:DateTime.UtcNow.AddHours(-i)});
        await ApiFactory.DbExecAsync("INSERT INTO product_images(id,product_id,url,position)VALUES(UUID(),@id,'/media/products/second.webp',1),(UUID(),@id,'/media/products/first.webp',0)",new{id=ids[2]});
        Assert.Equal(403,(await seller.Get("/api/admin/products")).Status);Assert.Equal(403,(await seller.Get("/api/admin/products/"+ids[0])).Status);r=await admin.Get("/api/admin/products");Assert.True(r.Status==200,r.ToString());Assert.Equal(ids[2].ToString(),r.Json["items"]![0]!["id"]!.GetValue<string>());Assert.Equal(ids[0].ToString(),r.Json["items"]![2]!["id"]!.GetValue<string>());Assert.Equal("/media/products/first.webp",r.Json["items"]![0]!["image"]!.GetValue<string>());Assert.Equal(3,r.Json["status_counts"]!["pending"]!.GetValue<int>());
        r=await admin.Get("/api/admin/products?q=%20Product%201%20&seller_id="+sid);Assert.Single(r.Json["items"]!.AsArray());Assert.Equal(3,r.Json["status_counts"]!["pending"]!.GetValue<int>());Assert.Empty((await admin.Get("/api/admin/products?seller_id="+Guid.NewGuid())).Json["items"]!.AsArray());Assert.Equal(1,(await admin.Get("/api/admin/products?page_size=2&page=2")).Json["items"]!.AsArray().Count);
        r=await admin.Get("/api/admin/products/"+ids[2]);Assert.True(r.Status==200,r.ToString());Assert.Equal(sid,r.Json["seller"]!["id"]!.GetValue<string>());Assert.NotNull(r.Json["required_details"]);Assert.NotNull(r.Json["variants"]);Assert.Equal(2,r.Json["images"]!.AsArray().Count);Assert.Equal(404,(await admin.Get("/api/admin/products/"+Guid.NewGuid())).Status);Assert.Equal(422,(await admin.Get("/api/admin/products?status=unknown")).Status);Assert.Equal(422,(await admin.Get("/api/admin/products?page=0")).Status);
        Assert.Equal(403,(await seller.Put("/api/admin/products/"+ids[2]+"/images",new{images=new[]{"/media/products/a.webp"}})).Status);Assert.Equal(422,(await admin.Put("/api/admin/products/"+ids[2]+"/images",new{images=new[]{"https://invalid.test/a.webp"}})).Status);Assert.Equal(422,(await admin.Put("/api/admin/products/"+ids[2]+"/images",new{images=new[]{"/media/products/a.webp","/media/products/a.webp"}})).Status);
        r=await admin.Put("/api/admin/products/"+ids[2]+"/images",new{images=new[]{"/media/products/new.webp","/media/products/next.webp"}});Assert.True(r.Status==200,r.ToString());Assert.Equal("pending",r.Json["status"]!.GetValue<string>());Assert.Equal("/media/products/new.webp",r.Json["images"]![0]!.GetValue<string>());
        r=await admin.Put("/api/admin/products/"+ids[2]+"/videos",new{videos=new[]{new{url="/media/videos/new.mp4",poster_url="/media/products/new.webp",title="Synthetic video",duration_s=20}}});Assert.True(r.Status==200,r.ToString());Assert.Single(r.Json["videos"]!.AsArray());await admin.Put("/api/admin/settings",new{feature_product_videos=false});Assert.Equal("videos_off",(await admin.Put("/api/admin/products/"+ids[2]+"/videos",new{videos=new[]{new{url="/media/videos/blocked.mp4"}}})).ErrorCode);Assert.Equal(200,(await admin.Put("/api/admin/products/"+ids[2]+"/videos",new{videos=Array.Empty<object>()})).Status);
        await ApiFactory.DbExecAsync("CREATE TRIGGER synthetic_product_media_fail BEFORE INSERT ON audit_logs FOR EACH ROW BEGIN IF NEW.action='product.images' THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Synthetic media rollback'; END IF; END");try{Assert.Equal(500,(await admin.Put("/api/admin/products/"+ids[2]+"/images",new{images=new[]{"/media/products/rolled-back.webp"}})).Status);Assert.Equal("/media/products/new.webp",(await admin.Get("/api/admin/products/"+ids[2])).Json["images"]![0]!.GetValue<string>());}finally{await ApiFactory.DbExecAsync("DROP TRIGGER synthetic_product_media_fail");}
        static MultipartFormDataContent Upload(byte[] bytes,string name){var form=new MultipartFormDataContent();form.Add(new ByteArrayContent(bytes),"file",name);return form;}
        byte[] mp4=[0,0,0,24,0x66,0x74,0x79,0x70,0x69,0x73,0x6f,0x6d,0,0,0,0,0,0,0,0];Assert.Equal(201,(await admin.Post("/api/admin/products/videos",Upload(mp4,"synthetic.mp4"))).Status);Assert.Equal("invalid_image",(await admin.Post("/api/admin/products/images",Upload([0,1,2,3],"bad.png"))).ErrorCode);using var bitmap=new SkiaSharp.SKBitmap(200,200);bitmap.Erase(SkiaSharp.SKColors.Blue);using var image=SkiaSharp.SKImage.FromBitmap(bitmap);using var encoded=image.Encode(SkiaSharp.SKEncodedImageFormat.Png,100);Assert.Equal(201,(await admin.Post("/api/admin/products/images",Upload(encoded.ToArray(),"synthetic.png"))).Status);
        await ApiFactory.DbExecAsync("UPDATE products SET status='approved' WHERE id=@id",new{id=ids[2]});Assert.Equal(2,(await admin.Get("/api/admin/products")).Json["total"]!.GetValue<int>());Assert.Single((await admin.Get("/api/admin/products?status=approved")).Json["items"]!.AsArray());
    }
}
